export class ConfidenceInformedSelfConsistency {
  constructor() {
    this.threshold = 0.7;
  }

  adjustPrediction(prediction, confidence) {
    if (confidence < this.threshold) {
      return { ...prediction, adjusted: true, reason: 'Low confidence adjustment' };
    }
    return { ...prediction, adjusted: false };
  }

  setThreshold(newThreshold) {
    this.threshold = newThreshold;
  }
}

// Example Usage
const cisc = new ConfidenceInformedSelfConsistency();
const prediction = { result: 'positive', confidence: 0.65 };
const adjustedPrediction = cisc.adjustPrediction(prediction, prediction.confidence);
console.log(adjustedPrediction);